import numpy as np
from scipy.signal import hilbert

def compute_hilbert_transform(a: np.ndarray, b: np.ndarray, dtype=np.float64) -> np.ndarray:
    if not np.issubdtype(a.dtype, np.number) or not np.issubdtype(b.dtype, np.number):
        raise TypeError("Input arrays must contain numeric types.")

    if not np.can_cast(a.dtype, dtype, 'safe') or not np.can_cast(b.dtype, dtype, 'safe'):
        raise TypeError(f"Cannot safely cast arrays to {dtype}.")

    stacked = np.vstack((a, b))
    analytic_signal = hilbert(stacked)
    return np.imag(analytic_signal)

